   const workbook=new ExcelJS.Workbook();const sheet=workbook.addWorksheet("Result");
   sheet.mergeCells("A1:C3");sheet.mergeCells("D1:J2");sheet.getCell("D1").value="SCHOOL NAME";sheet.getCell("D1").font={bold:true,size:18};
   sheet.getCell("D3").value="STUDENT RESULT";sheet.getCell("D3").font={bold:true,size:14};
   [["A4","Student Name"],["A5","Admission Number"],["E5","Class"],["A6","Term"],["E6","Session"]].forEach(([cell,value])=>sheet.getCell(cell).value=value);
   const headers=["Subject",...components.map(x=>x.label),"Total","Grade","Status"];const letter=(index:number)=>{let n=index+1,v="";while(n){n--;v=String.fromCharCode(65+n%26)+v;n=Math.floor(n/26);}return v;};
   headers.forEach((value,index)=>{const cell=sheet.getCell(9,index+1);cell.value=value;cell.font={bold:true};cell.border={bottom:{style:"thin"}};});
