   const output=await workbook.xlsx.writeBuffer();
   if(useHere){const totalCol=letter(components.length+1),gradeCol=letter(components.length+2),statusCol=letter(components.length+3);setFile(new File([output],"SchoolPro-Inbuilt-Result.xlsx",{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}));setConfig({...config,name:"SchoolPro inbuilt result",sheet_name:"Result",start_row:10,field_cells:{...initialFields},columns:{subject:"A",total:totalCol,grade:gradeCol,status:statusCol},component_columns:Object.fromEntries(components.map((c,i)=>[c.key,letter(i+1)])),custom_fields:[],logo_cell:"A1:C3",photo_cell:"K1:L4",teacher_signature_cell:"A35:C37",principal_signature_cell:"H35:J37",qr_cell:"K35"});}
