 const validateMappings=()=>{const problems:string[]=[];const cell=/^[A-Z]{1,3}[1-9][0-9]*(?::[A-Z]{1,3}[1-9][0-9]*)?$/,col=/^[A-Z]{1,3}$/;const cells:Array<[string,string]>=[...Object.entries(config.field_cells).map(([k,v])=>[k,String(v)] as [string,string]),...config.custom_fields.filter(x=>x.enabled!==false).map(x=>[x.label,x.cell] as [string,string]),["logo",config.logo_cell],["student photo",config.photo_cell],["principal signature",config.principal_signature_cell],["teacher signature",config.teacher_signature_cell],["verification QR",config.qr_cell]];cells.filter(([,v])=>v).forEach(([k,v])=>{if(!cell.test(v))problems.push(k+" has invalid cell "+v)});const ranges=cells.filter(([,v])=>cell.test(v)).map(([name,address])=>{const parts=address.split(":");const start=cellPosition(parts[0]),end=cellPosition(parts[1]||parts[0]);if(end.col<start.col||end.row<start.row||end.col>=16384||end.row>=1048576)problems.push(name+" has an invalid Excel range.");return{name,address,start,end};});for(let i=0;i<ranges.length;i++)for(let j=i+1;j<ranges.length;j++){const a=ranges[i],b=ranges[j];if(a.address!==b.address&&a.start.col<=b.end.col&&b.start.col<=a.end.col&&a.start.row<=b.end.row&&b.start.row<=a.end.row)problems.push(a.name+" overlaps "+b.name+". Choose separate cells or ranges.");}const used=new Map<string,string[]>();cells.filter(([,v])=>cell.test(v)).forEach(([k,v])=>used.set(v,[...(used.get(v)||[]),k]));used.forEach((names,v)=>{if(names.length>1)problems.push(v+" is assigned to "+names.join(", "))});Object.entries(config.columns).filter(([,v])=>v).forEach(([k,v])=>{if(!col.test(String(v)))problems.push(k+" has invalid column "+v)});if(!config.columns.subject)problems.push("Subject column is required.");if(!config.columns.total)problems.push("Total column is required.");if(!Number.isInteger(Number(config.start_row))||Number(config.start_row)<1)problems.push("Subject start row must be 1 or greater.");if(Number(config.qr_size)<40||Number(config.qr_size)>300)problems.push("QR size must be between 40 and 300 px.");if(config.component_columns.__layout){const used=new Set<string>();for(const [col,max] of [["D",20],["E",20],["F",60]] as const){const keys:string[]=config.component_columns.__component_groups?.[col]||[];if(keys.reduce((sum,key)=>sum+Number(components.find(c=>c.key===key)?.maxScore||0),0)!==max)problems.push(`${col} must contain assessments totalling ${max} marks.`);for(const key of keys){if(used.has(key))problems.push("An assessment can belong to only one printed column.");used.add(key);}}}return problems};
